// Sets up an instance of `PermissionManagerHostApi` to handle messages through the `binary_messenger`.
void PermissionManagerHostApi::SetUp(
  flutter::BinaryMessenger* binary_messenger,
  PermissionManagerHostApi* api) {
  PermissionManagerHostApi::SetUp(binary_messenger, api, "");
}

void PermissionManagerHostApi::SetUp(
  flutter::BinaryMessenger* binary_messenger,
  PermissionManagerHostApi* api,
  const std::string& message_channel_suffix) {
  const std::string prepended_suffix = message_channel_suffix.length() > 0 ? std::string(".") + message_channel_suffix : "";
  {
    BasicMessageChannel<> channel(binary_messenger, "dev.flutter.pigeon.mapmetrics.PermissionManagerHostApi.requestLocationPermissions" + prepended_suffix, &GetCodec());
    if (api != nullptr) {
      channel.SetMessageHandler([api](const EncodableValue& message, const flutter::MessageReply<EncodableValue>& reply) {
        try {
          const auto& args = std::get<EncodableList>(message);
          const auto& encodable_explanation_arg = args.at(0);
          if (encodable_explanation_arg.IsNull()) {
            reply(WrapError("explanation_arg unexpectedly null."));
            return;
          }
          const auto& explanation_arg = std::get<std::string>(encodable_explanation_arg);
          api->RequestLocationPermissions(explanation_arg, [reply](ErrorOr<bool>&& output) {
            if (output.has_error()) {
              reply(WrapError(output.error()));
              return;
            }
            EncodableList wrapped;
            wrapped.push_back(EncodableValue(std::move(output).TakeValue()));
            reply(EncodableValue(std::move(wrapped)));
          });
        } catch (const std::exception& exception) {
          reply(WrapError(exception.what()));
        }
      });
    } else {
      channel.SetMessageHandler(nullptr);
    }
  }
}

